private void gvData_ValidatingEditor(object sender, DevExpress.XtraEditors.Controls.BaseContainerValidateEditorEventArgs e)
{
    DataRow drw = gvData.GetFocusedDataRow();
    switch (gvData.FocusedColumn.FieldName)
    {
        case SIM_Class_Subject.C_THEORYQUANTITYOFTRAINING:
            TotalRow(drw, TypeParse.ToInt32(e.Value), null, null);
            break;
        case SIM_Class_Subject.C_PRACTICEQUANTITYOFTRAINING:
            TotalRow(drw,null, TypeParse.ToInt32(e.Value), null);
            break;
        case SIM_Class_Subject.C_TESTQUANTITYOFTRAINING:
            TotalRow(drw,null, null, TypeParse.ToInt32(e.Value), null);
            break;
    }
}

